"""Preserve real bounded training observation and completed offline selector analysis."""
from pathlib import Path
import base64,hashlib,json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs'
MAIN=OUT/'stem_component12_20261011_v1';REF=OUT/'native_stem_scratch12_20261011_v3';QUEUE=OUT/'stem_component_queue_pulse_20261011_v2'
OPT=OUT/'stem_optimizer_setting_audit_20261011_v1';OPT.mkdir(exist_ok=False)
PAYLOADS=json.loads("{\"reference\":{\"1\":{\"base64\":\"\",\"expected_sha256\":\"cc090f05a11f502d56f1b6dea2e76450faffa6ef4db6a407d3ed421af2cd08e7\",\"expected_bytes\":3040},\"2\":{\"base64\":\"\",\"expected_sha256\":\"65053fe8ecc2b4e9e4165aeeed29d354f9b71c776f70fa1aacd7b9a9470fd7a2\",\"expected_bytes\":3041}},\"queue\":{\"1\":{\"base64\":\"\",\"sha256\":\"2bb6fc49fe4091b4c2d91c80f7f711d85d63a818bf373c3a8a2212990e36051f\",\"bytes\":1469},\"2\":{\"base64\":\"\",\"sha256\":\"c5aecf191bbaa5e793be1b81e460c424214f521708619806402fa42eb62db062\",\"bytes\":1468}},\"optimizer\":{\"1\":{\"base64\":\"\",\"sha256\":\"eff6a2f010839d59e4aecf65603d52325a17e4e178860e9b631b1c51d3870a30\",\"bytes\":1837},\"2\":{\"base64\":\"\",\"sha256\":\"95add44ed51ec6ec03a92b5229f85de98bff137f9171599c7c500decc43f3f30\",\"bytes\":1837}}}")
read=lambda p:json.loads(Path(p).read_bytes())
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,v):
    with Path(p).open('x',encoding='utf8') as f:json.dump(v,f,ensure_ascii=False,indent=2,allow_nan=False)
observations={}
for kind,folder,version in [('reference',REF,7),('queue',QUEUE,3),('optimizer',OPT,1)]:
    observations[kind]={};transport={}
    for seed in (1,2):
        d=PAYLOADS[kind][str(seed)];b=base64.b64decode(d['base64'],validate=True)
        expected_sha=d.get('expected_sha256',d.get('sha256'));expected_bytes=d.get('expected_bytes',d.get('bytes'))
        assert len(b)==expected_bytes and hashlib.sha256(b).hexdigest()==expected_sha
        name=(f'compact_payload_seed{seed}_v{version}.json' if kind=='reference' else f'remote_observation_seed{seed}_v{version}.json')
        with (folder/name).open('xb') as f:f.write(b)
        observations[kind][seed]=json.loads(b)
        transport[str(seed)]=dict(file=name,bytes=len(b),sha256=expected_sha,status='PASS_EXACT_REMOTE_BYTES_AND_SHA256')
    write(folder/(f'compact_transport_v{version}.json' if kind=='reference' else f'observation_transport_v{version}.json'),transport)
snapshot=read(MAIN/'training_observation_v22.json');verified=read(MAIN/'training_observation_v22_transport_verification.json')
progress=read(MAIN/'progress_v22.json')
assert progress['snapshot_sha256']==sha(MAIN/'training_observation_v22.json')==verified['verified_snapshot_sha256']
ref=observations['reference']
for seed in (1,2):
    assert ref[seed]['code_sha256_verified'] and not ref[seed]['failures']
    assert ref[seed]['runtime']['first100_parity.json']['all100_rows_exact']
    assert 0<=ref[seed]['completed_epochs']<=12 and all(p['same_live'] for p in ref[seed]['processes'].values())
write(REF/'compact_observation_v7.json',{str(s):ref[s] for s in (1,2)})
pairs=[]
for seed in (1,2):
    r=ref[seed];e=r['completed_epochs'];random=r['latest_metrics'];assert random['epoch']==e-1
    full=next(m for m in snapshot[f'seed{seed}']['jobs']['original_stem']['metrics'] if m['epoch']==e-1)
    a,b=full['test_coco_eval_bbox'],random['test_coco_eval_bbox']
    pairs.append(dict(seed=seed,epoch=e,enhanced_AP=100*a[0],random_native_AP=100*b[0],delta_AP_pp=100*(a[0]-b[0]),enhanced_APs=100*a[3],random_native_APs=100*b[3],delta_APs_pp=100*(a[3]-b[3])))
comparison=dict(status='ANALYZED_DESCRIPTIVE_PER_SEED_SAME_EPOCH_EARLY_LOGS',current_S_pairs=pairs,
    full_snapshot_sha256=sha(MAIN/'training_observation_v22.json'),random_native_observation_sha256=sha(REF/'compact_observation_v7.json'),
    all_seeds_preserved=True,fixed12_efficacy_established=False,root_cause_established=False,
    interpretation='Each seed is compared at its own latest completed random-reference epoch. Seed1 epoch3 negative, seed2 epoch4 positive. Both fixed12 endpoints remain pending; do not compare latest full9/11 against reference3/4.',
    new_model_forwards=0,new_optimizer_updates=0)
write(MAIN/'same_epoch_random_native_comparison_v4.json',comparison)
rs=read(REF/'execution_state_v5.json')
rs.update(supersedes='execution_state_v5.json',evidence='compact_observation_v7.json',transport_verification='compact_transport_v7.json exact SHA256 and byte length verified',
    completed_epochs={str(s):ref[s]['completed_epochs'] for s in (1,2)},optimizer_updates={str(s):ref[s]['runtime']['training_audit_live.json']['actual_optimizer_steps'] for s in (1,2)},
    latest_live_processes={str(s):ref[s]['processes'] for s in (1,2)})
write(REF/'execution_state_v6.json',rs)
queue=observations['queue']
for seed in (1,2):
    q=queue[seed]
    assert q['helper']['same_live'] and q['conductor']['same_live'] and q['conductor']['state']=='T' and q['reference']['same_live']
    assert q['code_SHA_verified'] and q['component_SHA_verified'] and q['failure'] is None and not q['pulses']
qs=read(QUEUE/'execution_state_v2.json')
qs.update(supersedes='execution_state_v2.json',evidence='remote_observation_seed1/2_v3.json',helpers={str(s):queue[s]['helper'] for s in (1,2)},queued_arms_started_by_helper=0)
write(QUEUE/'execution_state_v3.json',qs)
opt=observations['optimizer']
for seed in (1,2):
    a,b=opt[seed]['arms']['original_stem'],opt[seed]['arms']['native_stem_scratch']
    for k in ('optimizer','configured_ema','warmup','schedule'):assert a[k]==b[k],k
    for arm in (a,b):
        assert arm['runtime_coverage']['all_parameters_exactly_once'] and arm['runtime_coverage']['all_native_parameter_groups_unchanged']
    assert a['optimizer']['lr']==.0004 and a['optimizer']['params'][0]['lr']==.0002
write(OPT/'report.json',dict(status='ANALYZED_SOURCE_CONFIG_AND_RUNTIME_COVERAGE',
    arms_identical_optimizer_ema_warmup_schedule=True,
    initial_non_norm_backbone_including_Stem_lr=.0002,default_lr_including_norm_bn=.0004,
    parameter_coverage_exactly_once=True,stem_lost_optimizer_membership_found=False,
    scope='Bound resolved configurations and actual runtime coverage checks at initialization. This does not prove gradient magnitude or learning-rate optimality, nor explain the AP difference causally.',
    source_runtime_sha256=sha(ROOT/'英文小论文/code/original_stem12_20261011_v1/runtime.py'),
    new_model_forwards=0,new_optimizer_updates=0,observations={str(s):opt[s] for s in (1,2)}))
SEL=OUT/'native_selection_analysis12_20261011_v1'
validation=read(SEL/'CPU_validation_v1.json');CODE=ROOT/'英文小论文/code/native_selection_analysis12_20261011_v1'
assert validation['status']=='PASS_ACTUAL_INDEX_TIES_EDGES_INVALID_PRIORS_AND_NONLOCAL_GEOMETRY_CPU_FIXTURES'
p=read(CODE/'protocol.json')
assert validation['code_sha256']==p['files']
assert all(sha(CODE/n)==h for n,h in p['files'].items())
assert validation['fixed12_records_analyzed']==validation['model_forwards']==0
write(SEL/'execution_state_v1.json',dict(status='OFFLINE_NATIVE_SELECTION_ANALYSIS_READY_ACTUAL_FIXED12_PENDING',
    protocol=str(CODE/'protocol.json'),protocol_sha256=sha(CODE/'protocol.json'),CPU_validation='CPU_validation_v1.json',
    CPU_validation_sha256=sha(SEL/'CPU_validation_v1.json'),real_fixed12_records_analyzed=0,
    model_or_training_code_changed=False,new_training_configurations=0,new_model_forwards=0,new_optimizer_updates=0,
    required='Four terminal enhanced/reference seed1/2 packets, exact saved-EMA diagnostic replays and verified paired-stage analysis.',
    scope=p['scope'],goal_complete=False))
state=read(MAIN/'execution_state_v17.json')
full_epochs={f'seed{s}':len(snapshot[f'seed{s}']['jobs']['original_stem']['metrics']) for s in (1,2)}
control_epochs={f'{arm}_seed{s}':len(snapshot[f'seed{s}']['jobs'][arm]['metrics']) for s in (1,2) for arm in ('detail_lowres','highfreq_rgb')}
state.update(supersedes='execution_state_v17.json',evidence='training_observation_v22.json',baseline_comparison='progress_v22.json',
    reference_state='../native_stem_scratch12_20261011_v3/execution_state_v6.json',queue_helper_state='../stem_component_queue_pulse_20261011_v2/execution_state_v3.json',
    latest_full_completed_epochs=full_epochs,latest_active_control_completed_epochs=control_epochs,new_reference_epochs={f'seed{s}':ref[s]['completed_epochs'] for s in (1,2)},
    same_epoch_reference_comparison='same_epoch_random_native_comparison_v4.json',
    optimizer_setting_audit='../stem_optimizer_setting_audit_20261011_v1/report.json',
    actual_selection_analysis='../native_selection_analysis12_20261011_v1/execution_state_v1.json',
    latest_full_vs_same_epoch_pretrained_BASE='Enhanced full seed1 epoch9, seed2 epoch11; both AP/APs below cached same-epoch pretrained BASE. Enhanced-vs-random difference remains seed-dependent at same per-seed epoch3/4.',
    finding='Completed real offline selection consumer with tie-aware actual-ID handling and local/nonlocal regression support checks; CPU fixtures passed. No actual fixed12 records analyzed yet. All8 current trainers live.',
    previous_goal_turn='progress',current_goal_turn='progress',no_progress_streak=0,
    fixed12_complete=False,goal_complete=False,
    next='Finish exact12 EMA endpoints and native terminal closeouts; run isolated selection replay only after training/closeout completion and actual GPU idle. Then apply the ready paired offline analysis without attributing causal roots from local neighborhoods.')
for s in (1,2):
    state['current_live_trainers'][f'seed{s}']={a:snapshot[f'seed{s}']['jobs'][a]['processes'] for a in ('original_stem','detail_lowres','highfreq_rgb')}
    assert all(p['same_live'] for ps in state['current_live_trainers'][f'seed{s}'].values() for p in ps)
state['current_full_CUDA_peak_reserved_bytes']={f'seed{s}':snapshot[f'seed{s}']['jobs']['original_stem']['records']['training_audit_live.json']['CUDA_peak_reserved_bytes'] for s in (1,2)}
state['live_observation_transport'].update(metadata='observation_transport_v11.json',verification='training_observation_v22_transport_verification.json')
write(MAIN/'execution_state_v18.json',state)
full=read(OUT/'original_stem12_20261011_v1/execution_state_v20.json')
full.update(supersedes='execution_state_v20.json',authoritative_state='../stem_component12_20261011_v1/execution_state_v18.json')
write(OUT/'original_stem12_20261011_v1/execution_state_v21.json',full)
print(json.dumps(dict(status='PROGRESS_OFFLINE_SELECTION_ANALYSIS_COMPLETED_AND_REAL_JOBS_LIVE',pairs=pairs,
    full_completed_epochs=full_epochs,reference_completed_epochs={s:ref[s]['completed_epochs'] for s in (1,2)},
    offline_analysis_actual_fixed12_records=0,queued_arms_started=0),ensure_ascii=False))

